1	import Link from "next/link";
2	import { PageHeader } from "@/components/page-header";
3	import { Card, CardContent } from "@repo/ui/components/card";
4	import { Badge } from "@repo/ui/components/badge";
5	import { Button } from "@repo/ui/components/button";
6	import { RiskBadge } from "@/components/badges";
7	import { tickets, properties, pipelineStages } from "@/lib/data";
8	import { timeAgo, formatEur } from "@/lib/utils";
9	import { Phone, Mail, AlertTriangle, ArrowRight } from "lucide-react";
10	
11	export default function OverviewPage() {
12	  const unsolved = tickets.filter((t) => !["resolved", "rejected"].includes(t.status));
13	  const proposed = tickets.filter((t) => t.status === "proposed");
14	  const completed = tickets.filter((t) => t.status === "completed");
15	
16	  const kpis = [
17	    { label: "Awaiting your approval", value: proposed.length, accent: "amber" },
18	    { label: "In flight",              value: unsolved.filter((t) => ["awaiting_vendor", "scheduled", "in_progress"].includes(t.status)).length },
19	    { label: "Memory writes pending",  value: completed.length, accent: "emerald" },
20	    { label: "Resolved last 7d",       value: 12 },
21	  ] as const;
22	
23	  return (
24	    <div>
25	      <PageHeader
26	        title="Overview"
27	        subtitle="Pipeline across all properties"
28	        actions={
29	          <Button variant="outline" size="sm">
30	            Last 24h
31	          </Button>
32	        }
33	      />
34	
35	      <div className="space-y-6 p-8">
36	        {/* KPI row */}
37	        <div className="grid grid-cols-4 gap-4">
38	          {kpis.map((k) => (
39	            <Card key={k.label}>
40	              <CardContent className="p-5">
41	                <div className="text-xs uppercase tracking-wider text-muted-foreground">{k.label}</div>
42	                <div className={`mt-2 text-3xl font-semibold ${k.accent === "amber" ? "text-amber-700" : k.accent === "emerald" ? "text-emerald-700" : ""}`}>
43	                  {k.value}
44	                </div>
45	              </CardContent>
46	            </Card>
47	          ))}
48	        </div>
49	
50	        {/* Pipeline */}
51	        <div>
52	          <h2 className="mb-3 text-sm font-semibold uppercase tracking-wider text-muted-foreground">Pipeline</h2>
53	          <div className="grid grid-cols-6 gap-3">
54	            {pipelineStages.map((stage) => {
55	              const stageTickets = tickets.filter((t) => t.status === stage.id);
56	              return (
57	                <div key={stage.id} className="rounded-lg border bg-background p-3">
58	                  <div className="mb-2 flex items-center justify-between">
59	                    <div className="text-xs font-medium">{stage.label}</div>
60	                    <span className="rounded bg-muted px-1.5 text-[11px] font-mono">{stageTickets.length}</span>
61	                  </div>
62	                  <p className="mb-3 text-[11px] leading-snug text-muted-foreground">{stage.description}</p>
63	                  <div className="space-y-2">
64	                    {stageTickets.map((t) => {
65	                      const prop = properties.find((p) => p.id === t.propertyId);
66	                      return (
67	                        <Link
68	                          key={t.id}
69	                          href={`/ticket/${t.id}`}
70	                          className="block rounded border bg-card p-2 hover:border-foreground/40"
71	                        >
72	                          <div className="flex items-center justify-between text-[10px] text-muted-foreground">
73	                            <span className="font-mono">{t.num}</span>
74	                            <RiskBadge risk={t.risk} />
75	                          </div>
76	                          <div className="mt-1 line-clamp-2 text-xs font-medium">{t.subject}</div>
77	                          <div className="mt-1 text-[10px] text-muted-foreground">{prop?.name}</div>
78	                        </Link>
79	                      );
80	                    })}
81	                  </div>
82	                </div>
83	              );
84	            })}
85	          </div>
86	        </div>
87	
88	        {/* Awaiting approval — call to action */}
89	        {proposed.length > 0 && (
90	          <Card className="border-amber-200 bg-amber-50/40">
91	            <CardContent className="p-5">
92	              <div className="mb-3 flex items-center gap-2">
93	                <AlertTriangle className="h-4 w-4 text-amber-700" />
94	                <h3 className="text-sm font-semibold">Awaiting your approval ({proposed.length})</h3>
95	              </div>
96	              <div className="space-y-2">
97	                {proposed.map((t) => {
98	                  const prop = properties.find((p) => p.id === t.propertyId);
99	                  return (
100	                    <Link
101	                      key={t.id}
102	                      href={`/ticket/${t.id}`}
103	                      className="flex items-center justify-between rounded-md border bg-background p-3 hover:border-foreground/40"
104	                    >
105	                      <div className="flex min-w-0 items-center gap-3">
106	                        {t.source === "voice" ? <Phone className="h-3.5 w-3.5 text-muted-foreground" /> : <Mail className="h-3.5 w-3.5 text-muted-foreground" />}
107	                        <div className="min-w-0">
108	                          <div className="flex items-center gap-2 text-sm font-medium">
109	                            <span className="truncate">{t.subject}</span>
110	                            <RiskBadge risk={t.risk} />
111	                          </div>
112	                          <div className="text-xs text-muted-foreground">
113	                            {prop?.name} · {t.raisedBy} · {timeAgo(t.createdAt)} ago
114	                            {t.proposal && <> · proposes {t.proposal.proposedAction.vendor} · {formatEur(t.proposal.proposedAction.estimateEur)}</>}
115	                          </div>
116	                        </div>
117	                      </div>
118	                      <ArrowRight className="h-4 w-4 text-muted-foreground" />
119	                    </Link>
120	                  );
121	                })}
122	              </div>
123	            </CardContent>
124	          </Card>
125	        )}
126	
127	        {/* Memory writes pending */}
128	        {completed.length > 0 && (
129	          <Card className="border-emerald-200 bg-emerald-50/40">
130	            <CardContent className="p-5">
131	              <div className="mb-3">
132	                <h3 className="text-sm font-semibold">Memory writes pending — vendor closed the job</h3>
133	                <p className="text-xs text-muted-foreground">Memory is only proposed AFTER work completes — not at dispatch.</p>
134	              </div>
135	              <div className="space-y-2">
136	                {completed.map((t) => {
137	                  const prop = properties.find((p) => p.id === t.propertyId);
138	                  return (
139	                    <Link
140	                      key={t.id}
141	                      href={`/ticket/${t.id}`}
142	                      className="flex items-center justify-between rounded-md border bg-background p-3 hover:border-foreground/40"
143	                    >
144	                      <div>
145	                        <div className="text-sm font-medium">{t.subject}</div>
146	                        <div className="text-xs text-muted-foreground">
147	                          {prop?.name} · final cost {t.vendorJob && formatEur(t.vendorJob.finalCostEur ?? 0)} · save to v{t.memoryProposal?.targetVersion}?
148	                        </div>
149	                      </div>
150	                      <Badge variant="success">memory pending</Badge>
151	                    </Link>
152	                  );
153	                })}
